{
  "v": 1,
  "language": "ru",
  "kind": "phrase",
  "pos": "phrase",
  "headword": { "ru": "во́лосы вста́ли ды́бом", "plain": "волосы встали дыбом" },
  "overview": {
    "gloss": "one's hair stood on end (from fear/shock)",
    "facts": [
      { "label": "Register", "value": "neutral to colloquial, very common in speech" },
      { "label": "Structure", "value": "у + genitive (person) + волосы (subject) + встали дыбом (predicate)" },
      { "label": "Literal meaning", "value": "hair rose up like a mane/crest" }
    ],
    "notes": [
      "Almost always used with «у меня / у него / у неё» etc. to show whose hair it is: «у меня волосы встали дыбом».",
      "«Дыбом» is an old adverbial form meaning 'rearing up, standing erect'; it survives mainly in this idiom and a few others (e.g. «шерсть встала дыбом» about animals).",
      "Describes a strong reaction of fear, horror or shock, not literal hair movement."
    ]
  },
  "sections": [
    {
      "id": "phrase-structure",
      "title": { "en": "Word by word", "ru": "Разбор по словам" },
      "layout": "list",
      "rows": [
        {
          "ru": "во́лосы",
          "plain": "волосы",
          "gloss": "nom. pl. of «во́лос» — hair(s)",
          "note": "Subject of the sentence; plural form used collectively for 'hair on the head'."
        },
        {
          "ru": "вста́ли",
          "plain": "встали",
          "gloss": "past pl. of «встать» (pf.) — stood up, rose",
          "note": "Perfective past, agrees with plural subject «волосы»."
        },
        {
          "ru": "ды́бом",
          "plain": "дыбом",
          "gloss": "adverb — erect, rearing up, on end",
          "note": "Archaic instrumental-type adverb, now used almost only in this and similar fixed expressions."
        }
      ]
    },
    {
      "id": "phrase-usage",
      "title": { "en": "Usage & register", "ru": "Употребление и стиль" },
      "layout": "list",
      "rows": [
        {
          "ru": "у меня́ во́лосы вста́ли ды́бом",
          "plain": "у меня волосы встали дыбом",
          "gloss": "my hair stood on end",
          "note": "Most common personal form, used in speech and writing to describe sudden fear or shock.",
          "example": {
            "ru": "Когда я услышал шаги наверху, у меня волосы встали дыбом.",
            "en": "When I heard footsteps upstairs, my hair stood on end."
          }
        },
        {
          "ru": "от э́того расска́за у всех во́лосы вста́ли ды́бом",
          "plain": "от этого рассказа у всех волосы встали дыбом",
          "gloss": "everyone's hair stood on end from that story",
          "note": "Used for group reactions to something horrifying, often in narration or news style.",
          "example": {
            "ru": "От его рассказа о войне у всех волосы встали дыбом.",
            "en": "Everyone's hair stood on end from his story about the war."
          }
        }
      ]
    },
    {
      "id": "phrase-variants",
      "title": { "en": "Variants & synonyms", "ru": "Варианты и синонимы" },
      "layout": "list",
      "rows": [
        {
          "ru": "волосы вста́ют ды́бом",
          "plain": "волосы встают дыбом",
          "gloss": "imperfective present — one's hair stands/rises on end",
          "note": "Used for repeated or ongoing reactions, e.g. describing a habitual fear."
        },
        {
          "ru": "мура́шки по коже",
          "plain": "мурашки по коже",
          "gloss": "goosebumps (lit. 'little ants on the skin')",
          "note": "Near-synonym describing chills of fear or excitement, often used interchangeably."
        },
        {
          "ru": "кровь в жи́лах засты́ла",
          "plain": "кровь в жилах застыла",
          "gloss": "one's blood froze (in the veins)",
          "note": "More dramatic/literary synonym for extreme fear or shock."
        }
      ]
    }
  ]
}
